 static constexpr int routingWidth=26;
 static void drawFilterBars(juce::Graphics& g,juce::Rectangle<float> area,int mask){using namespace juce;float centre=area.getCentreX(),bar=(juce::jmin((float)routingWidth,area.getWidth())-2.f)*.5f;for(int f=0;f<2;++f){g.setColour(nd::colour((mask&(1<<f))?nd::colour(Colour(NEXUM_UI_ACCENT)):Colour(0xff142431)));g.fillRect(centre+(f==0?-bar-1.f:1.f),area.getY(),bar,5.f);}}
 static void drawFilterRouting(juce::Graphics& g,juce::Rectangle<float> area,int mask,juce::Colour colour){using namespace juce;drawFilterBars(g,area,mask);g.setColour(nd::colour(colour));g.setFont(FontOptions(11.f,Font::bold));g.drawText("F",area.withTrimmedTop(6),Justification::centred,false);}
 void drawLabel(juce::Graphics& g,juce::Label& label)override{if(auto* combo=dynamic_cast<juce::ComboBox*>(label.getParentComponent()))if((bool)combo->getProperties()["joinedLfoStrip"]){g.setColour(combo->findColour(juce::ComboBox::textColourId));g.setFont(juce::FontOptions(10.f,juce::Font::bold));g.drawText(combo->getText(),label.getLocalBounds(),juce::Justification::centredLeft,false);return;}if(auto* combo=dynamic_cast<juce::ComboBox*>(label.getParentComponent())){if((bool)combo->getProperties()["warpGroup"]){g.setColour(nd::colour(juce::Colour(combo->getSelectedItemIndex()>0?NEXUM_UI_ACCENT:0xff899eae)));g.setFont(juce::FontOptions(9.f,juce::Font::bold));g.drawText(combo->getText(),label.getLocalBounds(),juce::Justification::centred,false);return;}}if(auto* combo=dynamic_cast<juce::ComboBox*>(label.getParentComponent()))if((bool)combo->getProperties()["routingDisplay"]||(int)combo->getProperties()["filterRouteMask"]>0)return;nd::LiveTheme::drawLabel(g,label);}

