 OscModernTheme(){using namespace juce;setColour(ComboBox::backgroundColourId,nd::colour(Colour(0xff15212d)));setColour(ComboBox::outlineColourId,nd::colour(Colour(0xff304151)));setColour(ComboBox::textColourId,nd::colour(Colour(0xffdce9f5)));setColour(TextButton::buttonColourId,nd::colour(Colour(0xff202f3e)));setColour(TextButton::buttonOnColourId,nd::colour(Colour(NEXUM_UI_ACCENT)));setColour(TextButton::textColourOffId,nd::colour(Colour(0xffdce9f5)));setColour(TextButton::textColourOnId,nd::colour(Colour(0xff09131e)));setColour(Slider::textBoxTextColourId,nd::colour(Colour(0xffc6dded)));setColour(Slider::textBoxOutlineColourId,Colours::transparentBlack);setColour(Slider::textBoxBackgroundColourId,Colours::transparentBlack);setColour(Slider::trackColourId,nd::colour(Colour(0xff253e53)));setColour(Slider::thumbColourId,nd::colour(Colour(NEXUM_UI_ACCENT)));}
 void drawButtonBackground(juce::Graphics& g,juce::Button& button,const juce::Colour& colour,bool over,bool down)override{nd::Scope suitScope((bool)button.getProperties()["headerTab"]|| (bool)button.getProperties()["squareMainTab"]?"tab":(bool)button.getProperties()["oscHeader"]?"header":button.getProperties()["oscIcon"].toString().isNotEmpty()||button.getProperties()["rackRailIcon"].toString().isNotEmpty()?"icon":"button");using namespace juce;if((bool)button.getProperties()["joinedLfoStrip"]){g.fillAll(nd::colour(Colour(0xff0c1620)));if(over||down){g.setColour(nd::colour(Colour(NEXUM_UI_ACCENT)).withAlpha(down?.12f:.06f));g.fillRect(button.getLocalBounds());}if(!(bool)button.getProperties()["stripEnd"]){g.setColour(nd::colour(Colour(0xff304151)));g.drawVerticalLine(button.getWidth()-1,4.f,(float)button.getHeight()-4);}return;}if((bool)button.getProperties()["warpArrow"]){g.fillAll(nd::colour(Colour(0xff15212d)));if(over||down){g.setColour(nd::colour(Colour(NEXUM_UI_ACCENT)).withAlpha(down?.2f:.1f));g.fillRect(button.getLocalBounds());}return;}if(button.getProperties()["rackRailIcon"].toString().isNotEmpty()){if(button.getProperties()["rackRailIcon"].toString()=="remove"){g.setColour(nd::colour(nd::colour(Colour(down?0xff09121a:over?0xff182e3d:0xff0c1822))));g.fillRoundedRectangle(button.getLocalBounds().toFloat().reduced(.5f),nd::number("radius",2.f));}return;}if((bool)button.getProperties()["lightModuleHeader"]){auto r=button.getLocalBounds().toFloat();auto base=(bool)button.getProperties()["independentFilterHeader"]?UiStyle::filterHeader():UiStyle::moduleHeader();if(button.getProperties().contains("mixHeaderColour"))base=nd::colour(Colour((juce::uint32)(int)button.getProperties()["mixHeaderColour"]));if(!(bool)button.getProperties()["independentFilterHeader"]&&!(bool)button.getProperties()["mixGroupHeader"]){if((bool)button.getProperties()["filterSelected"]||button.getToggleState())base=nd::colour(Colour(0xffb7cbd8));if(over)base=base.brighter(.05f);if(down)base=base.darker(.06f);}g.setColour(nd::colour(base));if((bool)button.getProperties()["roundedModTab"]){Path shape;shape.addRoundedRectangle(0,0,r.getWidth(),r.getHeight(),nd::number("radius",4),nd::number("radius",4),true,true,false,false);g.fillPath(shape);}else g.fillRect(r);g.setColour(nd::colour(nd::colour(Colour(0xff728b9d))));if((bool)button.getProperties()["independentFilterHeader"])g.setColour(nd::colour(Colour(NEXUM_UI_ACCENT)).withAlpha(.6f));g.drawHorizontalLine(button.getHeight()-1,0.f,r.getRight());if(!(bool)button.getProperties()["headerEnd"]&&!(bool)button.getProperties()["roundedModTab"])g.drawVerticalLine(button.getWidth()-1,0.f,r.getBottom());if((bool)button.getProperties()["oscPowerHeader"]){g.setColour(nd::colour(button.getToggleState()?nd::colour(Colour(0xff137bbd)):Colour(0xff6f8493)));g.fillEllipse(8,button.getHeight()*.5f-3,6,6);}return;}if((bool)button.getProperties()["roundedModTab"]){auto area=button.getLocalBounds().toFloat();Path shape;shape.addRoundedRectangle(0,0,area.getWidth(),area.getHeight(),nd::number("radius",4),nd::number("radius",4),true,true,false,false);auto base=nd::colour(Colour(button.getToggleState()?0xff344b5d:0xff243442));if(over)base=base.brighter(.06f);g.setColour(nd::colour(down?base.darker(.06f):base));g.fillPath(shape);g.setColour(nd::colour(nd::colour(Colour(0xff486074))));g.drawHorizontalLine(button.getHeight()-1,0.f,(float)button.getWidth());if((bool)button.getProperties()["oscPowerHeader"]){g.setColour(nd::colour(button.getToggleState()?nd::colour(Colour(NEXUM_UI_ACCENT)):Colour(0xff64717b)));g.fillEllipse(8.f,button.getHeight()*.5f-3,6,6);}return;}auto assetBar=button.getProperties()["assetBar"].toString();if(assetBar.isNotEmpty()){g.fillAll(nd::colour(Colour(0xff1e2b32)));if(over||down){g.setColour(nd::colour(nd::colour(Colour(NEXUM_UI_ACCENT)).withAlpha(down?.16f:.07f)));g.fillRect(button.getLocalBounds());}if(assetBar!="name"){g.setColour(nd::colour(nd::colour(Colour(0xff486074)).withAlpha(.65f)));g.drawVerticalLine(0,4.f,(float)button.getHeight()-4);}return;}auto icon=button.getProperties()["oscIcon"].toString();if(icon=="pencil"||icon=="down"){g.fillAll(nd::colour(Colour(icon=="pencil"?0xff0c1620:0xff1e2b32)));if(over||down){g.setColour(nd::colour(nd::colour(Colour(NEXUM_UI_ACCENT)).withAlpha(down?.20f:.11f)));if(icon=="down")g.fillRect(button.getLocalBounds());else g.fillRoundedRectangle(button.getLocalBounds().toFloat().reduced(1.f),nd::number("radius",2.f));}return;}if((bool)button.getProperties()["squareMainTab"])return;if((bool)button.getProperties()["oscHeader"]){g.fillAll(nd::colour(Colour(((bool)button.getProperties()["filterSelected"]||((bool)button.getProperties()["headerTab"]&&button.getToggleState()))?0xff344b5d:over?(down?0xff253c50:0xff2b4052):0xff243442)));g.setColour(nd::colour(nd::colour(Colour(0xff486074))));g.drawHorizontalLine(button.getHeight()-1,0.f,(float)button.getWidth());if(!(bool)button.getProperties()["headerEnd"])g.drawVerticalLine(button.getWidth()-1,0.f,(float)button.getHeight());if((bool)button.getProperties()["oscPowerHeader"]){if(!(bool)button.getProperties()["headerEnd"])g.drawVerticalLine(button.getWidth()-1,0.f,(float)button.getHeight());float cy=button.getHeight()*.5f;g.setColour(nd::colour(button.getToggleState()?nd::colour(Colour(NEXUM_UI_ACCENT)):Colour(0xff64717b)));g.fillEllipse(8.f,cy-3.f,6.f,6.f);}return;}auto r=button.getLocalBounds().toFloat().reduced(.5f);auto base=colour;if(over)base=base.brighter(.12f);if(down)base=base.darker(.18f);g.setColour(nd::colour(base));g.fillRoundedRectangle(r,nd::number("radius",3.f));g.setColour(nd::colour(nd::colour(Colour(0xff344650))));g.drawRoundedRectangle(r,nd::number("radius",3.f),.7f);}
 void drawButtonText(juce::Graphics& g,juce::TextButton& button,bool over,bool down)override{nd::Scope suitScope((bool)button.getProperties()["headerTab"]|| (bool)button.getProperties()["squareMainTab"]?"tab":(bool)button.getProperties()["oscHeader"]?"header":button.getProperties()["oscIcon"].toString().isNotEmpty()||button.getProperties()["rackRailIcon"].toString().isNotEmpty()?"icon":"button");using namespace juce;if((bool)button.getProperties()["joinedLfoStrip"]){g.setColour(button.findColour(button.getToggleState()?TextButton::textColourOnId:TextButton::textColourOffId));g.setFont(FontOptions(9.f,Font::bold));g.fillEllipse(9.f,button.getHeight()*.5f-2,4,4);g.drawText(button.getButtonText(),button.getLocalBounds().withTrimmedLeft(12),Justification::centred,false);return;}if((bool)button.getProperties()["warpArrow"]){float cx=button.getWidth()*.5f,cy=button.getHeight()*.5f,sign=button.getButtonText()=="<"?-1.f:1.f;Path arrow;arrow.startNewSubPath(cx-sign*1.5f,cy-2);arrow.lineTo(cx+sign*1.5f,cy);arrow.lineTo(cx-sign*1.5f,cy+2);g.setColour(nd::colour(Colour(over||down?NEXUM_UI_ACCENT:0xff8298aa)));g.strokePath(arrow,PathStrokeType(1.f));return;}auto railIcon=button.getProperties()["rackRailIcon"].toString();if(railIcon.isNotEmpty()){float cx=button.getWidth()*.5f,cy=button.getHeight()*.5f;g.setColour(nd::colour(nd::colour(Colour(railIcon=="remove"?(over?0xffd9efff:0xffa8bdcc):(down?0xff084b77:over?0xff008fe0:0xff172c3c))).withMultipliedAlpha(button.isEnabled()?1.f:.4f)));Path icon;if(railIcon=="remove"){icon.startNewSubPath(cx+1,cy-5);icon.lineTo(cx-6,cy-5);icon.lineTo(cx-6,cy+5);icon.lineTo(cx+1,cy+5);icon.startNewSubPath(cx-2,cy);icon.lineTo(cx+6,cy);icon.startNewSubPath(cx+3,cy-3);icon.lineTo(cx+6,cy);icon.lineTo(cx+3,cy+3);}else{float direction=railIcon=="up"?-1.f:1.f;icon.startNewSubPath(cx-3.3f,cy-direction*1.8f);icon.lineTo(cx,cy+direction*1.8f);icon.lineTo(cx+3.3f,cy-direction*1.8f);}g.strokePath(icon,PathStrokeType(nd::number("stroke",1.6f),PathStrokeType::curved,PathStrokeType::rounded));return;}if((bool)button.getProperties()["roundedModTab"]){g.setColour(nd::colour(button.findColour(button.getToggleState()?TextButton::textColourOnId:TextButton::textColourOffId)));g.setFont(FontOptions(nd::number("fontSize",11.5f),Font::bold));auto area=button.getLocalBounds().withTrimmedRight((bool)button.getProperties()["sourceRingSpace"]?19:0);if((bool)button.getProperties()["oscPowerHeader"])area=area.withTrimmedLeft(24);g.drawText(button.getButtonText(),area,Justification::centred,false);return;}int filterMask=(int)button.getProperties()["filterRouteMask"];if(filterMask>0){drawFilterRouting(g,button.getLocalBounds().toFloat(),filterMask,button.findColour(TextButton::textColourOffId));return;}auto assetBar=button.getProperties()["assetBar"].toString();if(assetBar.isNotEmpty()){g.setColour(nd::colour(over?nd::colour(Colour(NEXUM_UI_ACCENT)):button.findColour(TextButton::textColourOffId)));float cy=button.getHeight()*.5f;Path arrow;if(assetBar=="name"){g.setFont(FontOptions(11.f));g.drawText(button.getButtonText(),button.getLocalBounds().withTrimmedLeft(6).withTrimmedRight(24),Justification::centredLeft,false);float cx=button.getWidth()-11.f;arrow.startNewSubPath(cx-3,cy-1.5f);arrow.lineTo(cx,cy+1.5f);arrow.lineTo(cx+3,cy-1.5f);}else{float cx=button.getWidth()*.5f,sign=assetBar=="prev"?-1.f:1.f;arrow.startNewSubPath(cx-sign*1.5f,cy-3);arrow.lineTo(cx+sign*1.5f,cy);arrow.lineTo(cx-sign*1.5f,cy+3);}g.strokePath(arrow,PathStrokeType(nd::number("stroke",1.3f),PathStrokeType::curved,PathStrokeType::rounded));return;}auto icon=button.getProperties()["oscIcon"].toString();if(icon.isNotEmpty()){float cx=button.getWidth()*.5f,cy=button.getHeight()*.5f;g.setColour(nd::colour(over?nd::colour(Colour(NEXUM_UI_ACCENT)):button.findColour(TextButton::textColourOffId)));Path path;if(icon=="pencil"){path.startNewSubPath(cx-4.5f,cy+4.5f);path.lineTo(cx-3.3f,cy+.8f);path.lineTo(cx+2.8f,cy-5.3f);path.lineTo(cx+5.3f,cy-2.8f);path.lineTo(cx-.8f,cy+3.3f);path.closeSubPath();g.strokePath(path,PathStrokeType(nd::number("stroke",1.1f),PathStrokeType::curved,PathStrokeType::rounded));g.drawLine(cx+1.4f,cy-3.9f,cx+3.9f,cy-1.4f,1.f);g.drawLine(cx-4.5f,cy+4.5f,cx-2.8f,cy+4.f,1.2f);}else{path.startNewSubPath(cx-4,cy-2);path.lineTo(cx,cy+2);path.lineTo(cx+4,cy-2);g.strokePath(path,PathStrokeType(nd::number("stroke",1.5f),PathStrokeType::curved,PathStrokeType::rounded));}return;}if((bool)button.getProperties()["squareMainTab"]){g.setColour(nd::colour(button.findColour(button.getToggleState()?TextButton::textColourOnId:TextButton::textColourOffId)));g.setFont(FontOptions(nd::number("fontSize",11.5f),Font::bold));g.drawText(button.getButtonText(),button.getLocalBounds().reduced(3,0),Justification::centred,false);return;}if((bool)button.getProperties()["oscLabelHeader"]||(bool)button.getProperties()["filterLabelHeader"]){g.setColour(nd::colour(button.findColour(button.getToggleState()?TextButton::textColourOnId:TextButton::textColourOffId).withMultipliedAlpha(button.isEnabled()?1.f:.5f)));g.setFont(FontOptions(nd::number("fontSize",11.5f),Font::bold));bool oscLabel=(bool)button.getProperties()["oscLabelHeader"];auto textArea=oscLabel?button.getLocalBounds().withTrimmedLeft((bool)button.getProperties()["compactPowerHeader"]?16:24).withTrimmedRight((bool)button.getProperties()["compactPowerHeader"]?0:3):button.getLocalBounds().reduced(3,0);g.drawText(button.getButtonText(),textArea,oscLabel?Justification::centredLeft:Justification::centred,false);return;}if((bool)button.getProperties()["sourceRingSpace"]){g.setColour(nd::colour(button.findColour(button.getToggleState()?TextButton::textColourOnId:TextButton::textColourOffId)));g.setFont(FontOptions(nd::number("fontSize",10),Font::bold));g.drawText(button.getButtonText(),button.getLocalBounds().withTrimmedRight(19),Justification::centred,false);return;}if(button.getWidth()<=36){g.setFont(FontOptions(nd::number("fontSize",10),Font::bold));g.setColour(nd::colour(button.findColour(TextButton::textColourOffId)));g.drawText(button.getButtonText(),button.getLocalBounds().reduced(1),Justification::centred,false);return;}LookAndFeel_V4::drawButtonText(g,button,over,down);}
 juce::Label* createSliderTextBox(juce::Slider& slider)override{auto* label=LookAndFeel_V4::createSliderTextBox(slider);label->setFont(juce::FontOptions(11.f));label->setBorderSize(juce::BorderSize<int>(1));return label;}
 juce::Font getComboBoxFont(juce::ComboBox& box)override{return juce::Font(juce::FontOptions(box.getWidth()<60?9.5f:12.f));}
 void positionComboBoxText(juce::ComboBox& box,juce::Label& label)override{if((bool)box.getProperties()["joinedLfoStrip"]){label.setBounds(8,0,juce::jmax(1,box.getWidth()-30),box.getHeight());label.setBorderSize(juce::BorderSize<int>(0));label.setFont(juce::FontOptions(10.f,juce::Font::bold));return;}label.setBounds((bool)box.getProperties()["warpGroup"]?box.getLocalBounds():juce::Rectangle<int>(3,0,juce::jmax(1,box.getWidth()-17),box.getHeight()));label.setBorderSize(juce::BorderSize<int>(0));label.setFont(getComboBoxFont(box));}
 void drawComboBox(juce::Graphics& g,int w,int h,bool,int,int,int,int,juce::ComboBox& box)override{nd::Scope suitScope("combo");using namespace juce;if((bool)box.getProperties()["joinedLfoStrip"]){g.fillAll(nd::colour(Colour(0xff0c1620)));g.setColour(nd::colour(Colour(0xff304151)));g.drawVerticalLine(w-1,4.f,(float)h-4);Path arrow;float cx=w-12.f,cy=h*.5f;arrow.startNewSubPath(cx-3,cy-1.5f);arrow.lineTo(cx,cy+1.5f);arrow.lineTo(cx+3,cy-1.5f);g.setColour(nd::colour(Colour(NEXUM_UI_ACCENT)));g.strokePath(arrow,PathStrokeType(1.2f));return;}if((bool)box.getProperties()["warpGroup"]){g.fillAll(nd::colour(Colour(0xff15212d)));return;}bool header=(bool)box.getProperties()["oscHeader"];g.setColour(nd::colour(header?((bool)box.getProperties()["lightModuleHeader"]?UiStyle::moduleHeader():Colour(0xff243442)):box.findColour(ComboBox::backgroundColourId)));g.fillRect(0,0,w,h);g.setColour(nd::colour(header?nd::colour(Colour(0xff486074)):box.findColour(ComboBox::outlineColourId)));if(header){g.drawHorizontalLine(h-1,0.f,(float)w);g.drawVerticalLine(w-1,0.f,(float)h);}else g.drawRect(0,0,w,h,1);int filterMask=(int)box.getProperties()["filterRouteMask"];if(filterMask>0)drawFilterRouting(g,juce::Rectangle<float>(0,0,(float)w-17,(float)h),filterMask,box.findColour(ComboBox::textColourId));else if((bool)box.getProperties()["routingDisplay"]){g.setColour(nd::colour(box.findColour(ComboBox::textColourId)));g.setFont(getComboBoxFont(box));int routingIndex=(int)box.getProperties().getWithDefault("routingIndex",box.getSelectedItemIndex());g.drawText(routingIndex>=0?box.getItemText(routingIndex):box.getText(),Rectangle<int>(3,0,w-20,h),Justification::centredLeft,false);}Path arrow;float cx=w-(w<80?6.f:12.f),cy=h*.5f;arrow.startNewSubPath(cx-3,cy-2);arrow.lineTo(cx,cy+1);arrow.lineTo(cx+3,cy-2);g.setColour(nd::colour(box.findColour(ComboBox::textColourId).withAlpha(box.isEnabled()?.8f:.3f)));g.strokePath(arrow,PathStrokeType(nd::number("stroke",1.5f)));}
 void drawRotarySlider(juce::Graphics& g,int x,int y,int w,int h,float value,float start,float end,juce::Slider& slider)override{nd::Scope suitScope("knob");using namespace juce;float r=15.f,cx=x+w*.5f,cy=y+h*.5f,k=r-4;auto accent=slider.getProperties().contains("macroColour")?Colour((juce::uint32)(int)slider.getProperties()["macroColour"]):slider.getProperties().contains("fxAccent")?Colour((juce::uint32)(int)slider.getProperties()["fxAccent"]):Colour(NEXUM_UI_ACCENT);if(!slider.isEnabled())accent=accent.withAlpha(.35f);
  Path track;track.addCentredArc(cx,cy,r,r,0,start,end,true);g.setColour(nd::colour(nd::colour(Colour(0xff0a1017))));g.strokePath(track,PathStrokeType(nd::number("stroke",3.5f)));Path active;active.addCentredArc(cx,cy,r,r,0,start,start+value*(end-start),true);g.setColour(nd::colour(accent));g.strokePath(active,PathStrokeType(nd::number("stroke",2.2f)));
  g.setColour(nd::colour(Colours::black.withAlpha(.45f)));g.fillEllipse(cx-k-1,cy-k+3,2*k+2,2*k+2);
  g.setGradientFill(ColourGradient(nd::colour(Colour(0xff8b9cab)),cx-k,cy-k,nd::colour(Colour(0xff0a1018)),cx+k,cy+k,false));g.fillEllipse(cx-k,cy-k,k*2,k*2);
  float face=jmax(1.f,k-2);g.setGradientFill(ColourGradient(nd::colour(Colour(0xff526779)),cx-face*.65f,cy-face,nd::colour(Colour(0xff17232f)),cx+face*.6f,cy+face,false));g.fillEllipse(cx-face,cy-face,face*2,face*2);
  Path shine;shine.addCentredArc(cx,cy,face-.5f,face-.5f,0,-1.1f,.75f,true);g.setColour(nd::colour(Colours::white.withAlpha(.22f)));g.strokePath(shine,PathStrokeType(nd::number("stroke",.8f)));
  float angle=start+value*(end-start);float sx=cx+std::sin(angle)*face*.36f,sy=cy-std::cos(angle)*face*.36f,ex=cx+std::sin(angle)*face*.83f,ey=cy-std::cos(angle)*face*.83f;g.setColour(nd::colour(Colours::black.withAlpha(.6f)));g.drawLine(sx+1,sy+1,ex+1,ey+1,2.5f);g.setColour(nd::colour(nd::colour(Colour(0xffe5f4ff))));g.drawLine(sx,sy,ex,ey,1.8f);
 }

